import{_ as i,o as a,c as o,a4 as t}from"./chunks/framework.vNSRaLQv.js";const _=JSON.parse('{"title":"Watch Bilibili On Toshiba TV Demo","description":"","frontmatter":{"title":"Watch Bilibili On Toshiba TV Demo","date":"2026-04-29T00:00:00.000Z"},"headers":[],"relativePath":"posts/3-新项目-Stdio-架构旧文档-2026-04-29至05-22_watch-bilibili-demo-flow-zh.md","filePath":"posts/3-新项目-Stdio-架构旧文档-2026-04-29至05-22_watch-bilibili-demo-flow-zh.md"}'),c={name:"posts/3-新项目-Stdio-架构旧文档-2026-04-29至05-22_watch-bilibili-demo-flow-zh.md"};function d(l,e,s,n,h,p){return a(),o("div",null,[...e[0]||(e[0]=[t(`<h1 id="watch-bilibili-on-toshiba-tv-demo" tabindex="-1">Watch Bilibili On Toshiba TV Demo <a class="header-anchor" href="#watch-bilibili-on-toshiba-tv-demo" aria-label="Permalink to &quot;Watch Bilibili On Toshiba TV Demo&quot;">​</a></h1><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>这条工作流是 HomeSense Studio 的第一个家庭娱乐主线演示流。它不是单纯的“打开一个 App”，而是把用户自然意图转成可追踪、可复用、可编排的设备执行链。</p><p>目标叙事：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>用户说：我想在东芝电视上看 B 站。</span></span>
<span class="line"><span>系统执行：解析意图和家庭上下文 -&gt; 执行米家电视场景 -&gt; 让小爱中枢补执行 -&gt; 连接 Android TV ADB -&gt; 查看包名 -&gt; 打开小电视 App。</span></span></code></pre></div><h2 id="当前实现" tabindex="-1">当前实现 <a class="header-anchor" href="#当前实现" aria-label="Permalink to &quot;当前实现&quot;">​</a></h2><p>Seeded workflow:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>Watch Bilibili On Toshiba TV Demo</span></span></code></pre></div><p>节点链路：</p><ol><li><code>start</code>：注入家庭场景输入，包括 <code>target_tv</code>、<code>set_top_box</code>、<code>app_package</code>。</li><li><code>code</code>：生成可展示的 intent/context route。</li><li><code>scene_execute</code>：调用 <code>mi-cli.scene_execute</code> 执行米家手动场景，比如“东芝电视开机”。</li><li><code>xiaoai</code>：调用 <code>mi-cli.speaker_execute</code>，让小爱音箱中枢执行补充指令。</li><li><code>executor_call</code> + <code>agent.dispatch</code>：通过 <code>mi_adb</code> adapter 执行 <code>adb-cli.ensure_connected</code>。</li><li><code>executor_call</code> + <code>agent.dispatch</code>：通过 <code>mi_adb</code> adapter 执行 <code>adb-cli.list_packages</code>。</li><li><code>executor_call</code> + <code>agent.dispatch</code>：通过 <code>mi_adb</code> adapter 执行 <code>adb-cli.launch_app</code>，目标包名为 <code>com.xiaodianshi.tv.yst</code>。</li><li><code>answer</code>：输出演示闭环结果。</li></ol><h2 id="证明点" tabindex="-1">证明点 <a class="header-anchor" href="#证明点" aria-label="Permalink to &quot;证明点&quot;">​</a></h2><ul><li><code>WorkflowRuntime</code> 可以跑多节点设备流程。</li><li><code>ExecutorGateway</code> 可以统一承接 <code>cli.invoke</code> 和 <code>agent.dispatch</code>。</li><li><code>Skill/CLI</code> 可以作为外部执行能力接入，不要求所有能力写死在后端。</li><li><code>agent.dispatch</code> 已经能把“目标 agent/adapter + task + payload”转成实际 CLI 执行。</li><li>虚拟设备阶段可以先形成可测试闭环，后续替换为真实 ADB / mi-cli / B 站 CLI。</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ol><li>把这条工作流接入 Chat intent 命中路径。</li><li>加入执行前 preview，让用户看到将要控制哪些设备。</li><li>加入失败分支：米家场景不存在、小爱执行失败、ADB 连接失败、包名不存在、红外设备未知。</li><li>把虚拟设备状态显示到 Studio 或设备侧栏，方便录屏展示。</li></ol>`,14)])])}const b=i(c,[["render",d]]);export{_ as __pageData,b as default};
